// Offline documentation reader. No compiler, guest, storage or network required.
(() => {
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pages=()=>window.C_MANUAL_PAGES||{};
  function entry(id){return window.lessonReferences?.manualKey(id);}
  function href(id){const key=entry(id);return key?'#/manual/'+key:'#/reference/'+id;}
  const online=link=>`<a href="${escape(link.url)}" target="_blank" rel="noopener noreferrer">${escape(link.title)} (online, internet required, new tab)</a>`;
  function render(key){
    const all=pages();
    if(!key)return `<a href="#/chapter/first-program/6">← Finding and reading C documentation</a><article class="manual-reader"><h1 tabindex="-1">C manual pages</h1><p>These ${Object.keys(all).length} included Linux manual entries work after you download the course for offline use. Search by function name or a word in its description.</p><label for="manual-search">Find a manual page</label><input id="manual-search" type="search" placeholder="For example: printf, fgets, allocate" autocomplete="off"><p id="manual-count" role="status">${Object.keys(all).length} entries</p><ul id="manual-index">${Object.entries(all).map(([id,p])=>`<li data-manual-search="${escape((id+' '+p.summary).toLowerCase())}"><a href="#/manual/${id}">${escape(p.name)}(${escape(p.section)})</a><p>${escape(p.summary)}</p></li>`).join('')}</ul><p><a href="manuals/NOTICE.md">Sources and licences</a></p></article>`;
    const p=all[key];if(!p)return '<h1 tabindex="-1">Manual page not included</h1><p><a href="#/manual">Search the included C manual pages →</a></p>';
    return `<a href="#/manual">← C manual pages</a><article class="manual-reader"><h1 tabindex="-1">${escape(p.name)}(${escape(p.section)})</h1><p class="manual-scope">Included Linux manual. C17 is the teaching baseline; check STANDARDS for ISO C, POSIX and Linux extensions. These pages describe Linux/glibc; an extension may be unavailable in the inline compiler or Browser Linux’s musl library.</p>${p.html}<footer aria-label="Manual source and licence"><p>Source: Linux man-pages 6.16 · <a href="manuals/source/${escape(key)}" download>Original source and copyright notice</a> · <a href="manuals/NOTICE.md">Licences and provenance</a></p></footer></article>`;
  }
  function reference(id){
    const included=entry(id);if(included)return render(included);
    const link=window.lessonReferences.catalog[id];if(!link)return '<h1 tabindex="-1">Reference not found</h1><p><a href="#/manual">C manual pages →</a></p>';
    const related=[];
    for(const chapter of COURSE.chapters)for(const topic of chapter.topics){
      const content=authoredLessons.content[chapter.id]?.topics[topic.id];if(!content)continue;
      if(lessonReferences.get(chapter,topic,content).links.some(ref=>ref.id===id))related.push({chapter,topic,content});
    }
    return `<article class="manual-reader"><a href="#/manual">C manual pages →</a><h1 tabindex="-1">Course notes: ${escape(link.title)}</h1><p>${escape(link.note)}</p><p>These excerpts are included with the course and work offline. Choose a lesson title to see its associated source, prepared input, and output.</p><details class="supplementary-references"><summary>Optional further reading (online)</summary><p>${online(link)}</p></details>${related.map(({chapter,topic,content})=>`<section><h2><a href="#/chapter/${chapter.id}/${topic.id}">${escape(topic.title)}</a></h2><p>${content.explanation}</p><p>${content.pitfall}</p><details><summary>Documentation question and answer</summary><p>${escape(lessonReferences.chapters[chapter.id].exercise.question)}</p><p>${escape(lessonReferences.chapters[chapter.id].exercise.answer)}</p></details></section>`).join('')}</article>`;
  }
  document.addEventListener('input',e=>{if(e.target.id!=='manual-search')return;const query=e.target.value.trim().toLowerCase();let n=0;document.querySelectorAll('[data-manual-search]').forEach(li=>{li.hidden=!li.dataset.manualSearch.includes(query);if(!li.hidden)n++;});document.getElementById('manual-count').textContent=n+' entries';});
  const helpKey='c-foundry:help-practice:v1';
  function savedHelp(){try{return JSON.parse(localStorage.getItem(helpKey))||{};}catch(_){return {};}}
  function saveHelp(){const state=savedHelp();for(const id of ['help-prediction','help-failure','help-transfer']){const el=document.getElementById(id);if(el)state[id]=el.value;}try{localStorage.setItem(helpKey,JSON.stringify(state));}catch(_){}}
  function sections(){const doc=new DOMParser().parseFromString(pages()['printf.3'].html,'text/html');return [...doc.querySelectorAll('.manual-text>section.Sh')].map(section=>({id:section.querySelector('h2')?.id,title:section.querySelector('h2')?.textContent.replace(/\s+/g,' ').trim(),html:section.outerHTML})).filter(section=>section.id);}
  function practice(){return `<section class="help-practice" aria-labelledby="help-goal"><h2 id="help-goal">1. Find printf’s return contract</h2><aside class="manual-section-callout" aria-label="Manual section numbers"><p><strong>Section 3 is for C library functions.</strong></p><p><code>printf(3)</code> is the C function’s manual; <code>printf(1)</code> is the shell command’s manual.</p></aside><p>Open <strong>printf(3)</strong> and choose <strong>RETURN VALUE</strong> in <strong>Manual section</strong>. Read the first paragraph for successful printf calls and the last for errors. The middle paragraphs describe other functions; skip them for this exercise.</p><button type="button" id="help-open-manual" aria-expanded="false" aria-controls="help-manual">Open printf(3)</button><section id="help-manual" class="help-manual" hidden aria-label="printf manual"><div class="help-manual-controls"><div class="help-manual-toolbar"><strong>printf(3) · included manual</strong><button type="button" id="help-close-manual">Close manual</button></div><label for="help-manual-section">Manual section</label><select id="help-manual-section">${sections().map(s=>`<option value="${escape(s.id)}">${escape(s.title)}</option>`).join('')}</select></div><div id="help-manual-content" class="manual-reader"></div><p class="supporting">Linux/glibc manual; check STANDARDS for ISO C and extensions. You can ignore unfamiliar pointer annotations for now.</p><footer class="supporting"><p>Source: Linux man-pages 6.16 · <a href="manuals/source/printf.3" download>Original source</a> · <a href="manuals/NOTICE.md">Sources and licences</a></p></footer></section><h2>2. Predict before running</h2><p>The first call prints <code>Hi!</code> followed by a newline. What value will that call return? Include the newline in your reasoning.</p><div class="help-answer-fields"><label for="help-prediction">Predicted character count<input id="help-prediction" type="number" min="0" step="1" inputmode="numeric"></label><label for="help-failure">On output or encoding failure<select id="help-failure"><option value="">Choose from the manual</option><option value="zero">Always zero</option><option value="negative">A negative value</option><option value="count">The requested character count</option></select></label></div><button type="button" id="help-check-contract">Check my reading</button><p id="help-contract-feedback" role="status"></p><p id="help-run-evidence" role="status">Run the program below to compare its count= line with your prediction.</p></section>`;}
  function transfer(instruction){return `<section class="help-transfer"><h2>4. Apply the rule to a new string</h2><p>${escape(instruction)}</p><label for="help-transfer">Predicted count for C, a percent sign and a newline<input id="help-transfer" type="number" min="0" step="1" inputmode="numeric"></label><p id="help-transfer-feedback" role="status">Run your changed program, then inspect count= in Console. Does %% count as one printed character or two?</p><details class="help-linux-extension"><summary>Use man in the Linux terminal</summary><p>Practise the same lookup with <code>man 3 printf</code>. The terminal has visible page buttons, a search field and <strong>Close manual · q</strong>. After closing the manual, run <code>man -k printf</code> to search the available names and descriptions. Return here to use the contract in your code.</p><a class="primary-link" href="#/linux/first-program/${encodeURIComponent('man 3 printf')}">Practise man in Linux →</a></details></section>`;}
  function showSection(){const section=sections().find(s=>s.id===document.getElementById('help-manual-section').value);const host=document.getElementById('help-manual-content');if(!section||!host)return;host.innerHTML=section.html;for(const a of host.querySelectorAll('a.permalink'))a.replaceWith(a.textContent);const panel=document.getElementById('help-manual');if(panel.getBoundingClientRect().top<0)panel.scrollIntoView({block:'start'});}
  document.addEventListener('click',event=>{
    if(event.target.id==='help-open-manual'){const el=document.getElementById('help-manual');el.hidden=false;event.target.setAttribute('aria-expanded','true');showSection();document.getElementById('help-manual-section').focus();}
    if(event.target.id==='help-close-manual'){document.getElementById('help-manual').hidden=true;const open=document.getElementById('help-open-manual');open.setAttribute('aria-expanded','false');open.focus();}
    if(event.target.id==='help-check-contract'){
      const raw=document.getElementById('help-prediction').value,failure=document.getElementById('help-failure').value,feedback=document.getElementById('help-contract-feedback');
      if(raw===''||!failure)feedback.textContent='Enter a character count and choose a failure result first. Use RETURN VALUE in the manual.';
      else if(Number(raw)===4&&failure==='negative')feedback.textContent='Correct: H, i, ! and the newline are four transmitted characters. The string’s terminating null byte is not printed. Output or encoding failure returns a negative value. Now test the prediction with Run code below.';
      else feedback.textContent=(Number(raw)===5?'The terminating null byte is not transmitted. ':Number(raw)===0?'printf reports transmitted characters on success; it does not always return zero. ':'Count H, i, ! and the newline. ')+(failure!=='negative'?'Read the failure rule in RETURN VALUE too. ':'')+'Revise your prediction, then check again.';
      saveHelp();
    }
  });
  document.addEventListener('change',event=>{if(event.target.id==='help-manual-section')showSection();if(['help-prediction','help-failure','help-transfer'].includes(event.target.id))saveHelp();});
  document.addEventListener('input',event=>{if(['help-prediction','help-transfer'].includes(event.target.id))saveHelp();});
  window.addEventListener('c-foundry:route',()=>{const state=savedHelp();for(const id of ['help-prediction','help-failure','help-transfer']){const el=document.getElementById(id);if(el&&state[id]!==undefined)el.value=state[id];}});
  window.addEventListener('c-foundry:program-run',event=>{
    if(event.detail?.lessonId!=='example-first-program-6')return;
    const actual=document.getElementById('output')?.textContent.match(/(?:^|\n)count=(\d+)/)?.[1];if(actual===undefined)return;
    const original=event.detail.code.includes('printf("Hi!\\n")'),changed=event.detail.code.includes('printf("C%%\\n")');
    const host=document.getElementById(original?'help-run-evidence':'help-transfer-feedback');if(!host)return;
    const prediction=document.getElementById(original?'help-prediction':'help-transfer').value;
    host.textContent=(prediction===''?'Console shows count='+actual+'.':Number(prediction)===Number(actual)?'Your prediction matches Console: count='+actual+'.':'You predicted '+prediction+'; Console shows count='+actual+'.')+(original?' The original call transmitted three visible characters and one newline.':changed?' C, one percent sign and a newline are three transmitted characters. %% produces one percent sign.':' This run used another edit. Use its actual output to explain the character count.');
  });

  window.cManuals={entry,href,render,reference,practice,transfer};
})();
